      SUBROUTINE FIX23LCC     REVISE REFERENCES FOR ALGEBRAIC OPERATIONS PRECEDING PRESENT ELEMENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM24D.CIN'CC     LOCAL VARIABLESC      INTEGER         TYPET      EQUIVALENCE     (FAKE,LAKE)      EXTERNAL        IDATACC--------------------------------------------------------------------C      NN = 0C   10 NN = NN + 1      III = ISTOR(NN)      TYPET = IDATA(III)      IF (TYPET .EQ. 23) GO TO 2300      GO TO 6000CC     23. -- ALGEBRAIC OPERATIONC 2300 K1REG = IDATA(III+1)      K2REG = IDATA(III+2)      JREG = IDATA(III+4)      K1TIE = TIE(III+1)      K2TIE = TIE(III+2)      JTIE = TIE(III+4)      KRCOM = II + 1      IF (K1TIE .EQ. 100 .AND. K1REG .EQ. KRCOM) K1REG = I + 1      IF (K2TIE .EQ. 100 .AND. K2REG .EQ. KRCOM) K2REG = I + 1      IF (JTIE .EQ. 100 .AND. JREG .EQ. KRCOM) JREG = I + 1      LAKE = K1REG      DATA(III+1) = FAKE      LAKE = K2REG      DATA(III+2) = FAKE      LAKE = JREG      DATA(III+4) = FAKE      GO TO 6000C 6000 IF (NN .LT. NEL) GO TO 10C 6200 RETURN      END